From 7b0a4a0bdd8b972600826a5bfff777d8542419e6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 21:26:57 +0100
Subject: [PATCH] applets/batterymonitor: add a global shortcut to block sleep
 and screen locking

Manually blocking sleep and screen locking was only possible by opening
the applet and clicking its switch. Add a global action, unbound by
default, that toggles the same block and shows the usual OSD feedback.

BUG: 513546
---
 applets/batterymonitor/plugin/CMakeLists.txt  |  3 +++
 .../plugin/inhibitmonitor_p.cpp               | 19 +++++++++++++++++++
 .../batterymonitor/plugin/inhibitmonitor_p.h  |  3 +++
 3 files changed, 25 insertions(+)

diff --git a/applets/batterymonitor/plugin/CMakeLists.txt b/applets/batterymonitor/plugin/CMakeLists.txt
index d841070df..35eaf94c7 100644
--- a/applets/batterymonitor/plugin/CMakeLists.txt
+++ b/applets/batterymonitor/plugin/CMakeLists.txt
@@ -1,6 +1,8 @@
 # SPDX-FileCopyrightText: 2024 Bohdan Onofriichuk <bogdan.onofriuchuk@gmail.com>
 # SPDX-License-Identifier: BSD-3-Clause

+add_definitions(-DTRANSLATION_DOMAIN=\"plasma_applet_org.kde.plasma.battery\")
+
 ecm_add_qml_module(batterymonitorplugin URI org.kde.plasma.private.batterymonitor GENERATE_PLUGIN_SOURCE)

 target_sources(batterymonitorplugin PRIVATE
@@ -17,6 +19,7 @@ target_link_libraries(batterymonitorplugin PRIVATE
         Qt::Gui
         KF6::Service
         KF6::I18n
+        KF6::GlobalAccel
 )

 ecm_qt_declare_logging_category(batterymonitorplugin
diff --git a/applets/batterymonitor/plugin/inhibitmonitor_p.cpp b/applets/batterymonitor/plugin/inhibitmonitor_p.cpp
index d1247ebda..ceb29468d 100644
--- a/applets/batterymonitor/plugin/inhibitmonitor_p.cpp
+++ b/applets/batterymonitor/plugin/inhibitmonitor_p.cpp
@@ -6,12 +6,16 @@

 #include "inhibitmonitor_p.h"

+#include <QAction>
 #include <QDBusConnectionInterface>
 #include <QDBusInterface>
 #include <QDBusMetaType>
 #include <QDBusReply>
 #include <QGuiApplication>

+#include <KGlobalAccel>
+#include <KLocalizedString>
+
 InhibitMonitor &InhibitMonitor::self()
 {
     static InhibitMonitor inhibitMonitor;
@@ -19,7 +23,22 @@ InhibitMonitor &InhibitMonitor::self()
 }

 InhibitMonitor::InhibitMonitor()
+    : m_toggleAction(new QAction(this))
 {
+    m_toggleAction->setObjectName(QStringLiteral("toggle sleep and screen locking block"));
+    m_toggleAction->setProperty("componentName", QStringLiteral("plasmashell"));
+    m_toggleAction->setText(i18nc("@action global shortcut", "Block or Unblock Sleep and Screen Locking"));
+    m_toggleAction->setIcon(QIcon::fromTheme(QStringLiteral("system-suspend-inhibited")));
+    m_toggleAction->setShortcutContext(Qt::ApplicationShortcut);
+    connect(m_toggleAction, &QAction::triggered, this, [this] {
+        if (getInhibit()) {
+            uninhibit(false);
+        } else {
+            inhibit(i18n("The battery applet has enabled suppressing sleep and screen locking"), false);
+        }
+    });
+
+    KGlobalAccel::self()->setGlobalShortcut(m_toggleAction, QKeySequence());
 }

 InhibitMonitor::~InhibitMonitor()
diff --git a/applets/batterymonitor/plugin/inhibitmonitor_p.h b/applets/batterymonitor/plugin/inhibitmonitor_p.h
index cca48a9bf..13a7a0e7c 100644
--- a/applets/batterymonitor/plugin/inhibitmonitor_p.h
+++ b/applets/batterymonitor/plugin/inhibitmonitor_p.h
@@ -10,6 +10,8 @@
 #include <QString>
 #include <qtypes.h>

+class QAction;
+
 class InhibitMonitor : public QObject
 {
     Q_OBJECT
@@ -37,4 +39,5 @@ Q_SIGNALS:
 private:
     std::optional<uint> m_sleepInhibitionCookie;
     std::optional<uint> m_lockInhibitionCookie;
+    QAction *m_toggleAction;
 };
